// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("llama");
  draw("cuerpo");
});

// Llama de largo variable: largo > 0 la estira hacia arriba repitiendo la fila 4,
// largo < 0 la mete bajo el cuerpo. vivo enciende el núcleo en amarillo.
part("propulsion", ({ largo = 0, vivo = false }) => {
  move(0, -largo, () => draw("llama"));
  for (let i = 0; i < largo; i++) {
    const y = 4 - i;
    set_pixel(27, y, "#19191919");
    set_pixel(28, y, "#fbfbfbfb");
    set_pixel(29, y, "#cec2be");
    set_pixel(30, y, "#b75c24");
    fill_rect(31, y, 2, 1, "#dd600d");
    set_pixel(33, y, "#813a1e");
    set_pixel(34, y, "#a49191");
    set_pixel(35, y, "#f9f9f9f9");
    set_pixel(36, y, "#15151515");
  }
  draw("cuerpo");
  if (vivo) {
    fill_rect(31, 4, 2, 1, "#ec9e3c");
    fill_rect(31, 5, 2, 1, "#fde872");
  }
});

// Sensor cian encendido por niveles (0 = como la base).
part("sensor", ({ nivel = 0 }) => {
  if (nivel <= 0) return;
  const filas = [[26, 30, 33], [27, 29, 34], [28, 29, 35], [29, 29, 35], [30, 29, 35], [31, 29, 34], [32, 30, 33]];
  const [aro, centro, brillo] = cycle([
    ["#20dff9", "#35dff5", "#c0f8ff"],
    ["#55ebff", "#90f2ff", "#d8fbff"],
    ["#90f2ff", "#d8fbff", "#ffffff"],
  ], nivel - 1);
  for (const [y, x1, x2] of filas) fill_rect(x1, y, x2 - x1 + 1, 1, aro);
  fill_rect(30, 28, 4, 3, centro);
  fill_rect(31, 27, 2, 5, centro);
  set_pixel(30, 27, brillo);
  set_pixel(30, 28, brillo);
  if (nivel >= 3) fill_rect(31, 28, 2, 3, brillo);
});

// Punta amarilla destellando: 1 = aclara, 2 = blanca.
part("destello", ({ nivel = 0 }) => {
  if (nivel <= 0) return;
  const claro = nivel >= 2 ? "#ffffff" : "#fef3cc";
  const medio = nivel >= 2 ? "#ffe9a0" : "#ffd23a";
  fill_rect(30, 46, 2, 5, claro);
  fill_rect(32, 46, 1, 5, medio);
  set_pixel(33, 47, "#ffd23a");
  fill_rect(31, 51, 1, 4, claro);
  fill_rect(32, 51, 1, 3, medio);
  fill_rect(31, 55, 1, 3, medio);
  if (nivel >= 2) fill_rect(32, 54, 1, 3, "#ffd23a");
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
action("propulsor", { frames: 4, fps: 12, loop: true }, (f, { t }) => {
  draw("propulsion", { largo: cycle([0, 2, 1, -1], f), vivo: f === 1 });
});

action("aviso", { frames: 6, fps: 12, loop: false }, (f, { t }) => {
  const dy = cycle([0, 0, -1, -1, -2, -2], f);
  move(0, dy, () => {
    draw("propulsion", { largo: cycle([0, 1, 1, 2, 2, 2], f), vivo: f >= 3 });
    draw("sensor", { nivel: cycle([0, 1, 1, 2, 3, 3], f) });
    draw("destello", { nivel: cycle([0, 0, 0, 0, 1, 2], f) });
  });
});

